// Exact Boolean word functions; 64 independent input/measurement lanes at once.
// Constants stay immediate. Hash keys compare complete expressions and masks.
use super::{Program,QX,QCX,QCCX,QSWAP,QZERO,CINV,CZERO,CONE,CRNG};
use std::collections::HashMap;
#[derive(Clone,Copy,Debug,PartialEq,Eq,Hash,PartialOrd,Ord)]struct E{node:u32,mask:u64}
impl E{fn constant(v:u64)->Self{Self{node:0,mask:v}}fn flip(self,v:u64)->Self{Self{node:self.node,mask:self.mask^v}}}
#[derive(Clone,Copy)]struct N{k:u8,a:E,b:E,z:u64,o:u64}
#[derive(Default)]struct Aig{nodes:Vec<N>,memo:HashMap<(u8,E,E),u32>,random:HashMap<u32,E>}
impl Aig{
 fn known(&self,e:E)->(u64,u64){if e.node==0{return(!e.mask,e.mask);}let n=self.nodes[e.node as usize-1];((n.z&!e.mask)|(n.o&e.mask),(n.o&!e.mask)|(n.z&e.mask))}
 fn random(&mut self,slot:u32)->E{if let Some(&e)=self.random.get(&slot){return e;}let e=E{node:self.nodes.len()as u32+1,mask:0};self.nodes.push(N{k:0,a:E::constant(slot as u64),b:E::constant(0),z:0,o:0});self.random.insert(slot,e);e}
 fn intern(&mut self,k:u8,mut a:E,mut b:E)->E{if a>b{std::mem::swap(&mut a,&mut b);}let(az,ao)=self.known(a);let(bz,bo)=self.known(b);let(z,o)=if k==1{(az|bz,ao&bo)}else{((az&bz)|(ao&bo),(az&bo)|(ao&bz))};assert_eq!(z&o,0);if z|o==u64::MAX{return E::constant(o);}if let Some(&node)=self.memo.get(&(k,a,b)){return E{node,mask:0};}let node=self.nodes.len()as u32+1;self.nodes.push(N{k,a,b,z,o});self.memo.insert((k,a,b),node);E{node,mask:0}}
 fn and(&mut self,a:E,b:E)->E{
  if a.node==0&&b.node==0{return E::constant(a.mask&b.mask);}if a==E::constant(0)||b==E::constant(0){return E::constant(0);}if a==E::constant(u64::MAX){return b;}if b==E::constant(u64::MAX)||a==b{return a;}
  if a.node==b.node{let keep=!(a.mask^b.mask);let v=self.and(E{node:a.node,mask:0},E::constant(keep));return v.flip(a.mask&b.mask);}
  if a.node==0&&b.mask!=0{let v=self.and(a,E{node:b.node,mask:0});return v.flip(a.mask&b.mask);}if b.node==0&&a.mask!=0{return self.and(b,a);}
  for(x,y)in[(a,b),(b,a)]{if x.node!=0&&x.mask==0{let n=self.nodes[x.node as usize-1];if n.k==1{if n.a==y||n.b==y{return x;}if n.a==y.flip(u64::MAX)||n.b==y.flip(u64::MAX){return E::constant(0);}}}}
  self.intern(1,a,b)
 }
 fn xor(&mut self,a:E,b:E)->E{if a.node==0{return b.flip(a.mask);}if b.node==0{return a.flip(b.mask);}let mask=a.mask^b.mask;if a.node==b.node{return E::constant(mask);}let a=E{node:a.node,mask:0};let b=E{node:b.node,mask:0};for(x,y)in[(a,b),(b,a)]{let n=self.nodes[x.node as usize-1];if n.k==2{if n.a==y{return n.b.flip(mask);}if n.b==y{return n.a.flip(mask);}}}self.intern(2,a,b).flip(mask)}
 fn ite(&mut self,g:E,a:E,b:E)->E{if g==E::constant(0)||a==b{return b;}if g==E::constant(u64::MAX){return a;}let d=self.xor(a,b);let v=self.and(g,d);self.xor(b,v)}
 fn evaluate(&self,random:&[u64])->Vec<u64>{let mut values=Vec::with_capacity(self.nodes.len());let get=|e:E,v:&Vec<u64>|if e.node==0{e.mask}else{v[e.node as usize-1]^e.mask};for n in &self.nodes{let value=match n.k{0=>random[n.a.mask as usize],1=>get(n.a,&values)&get(n.b,&values),2=>get(n.a,&values)^get(n.b,&values),_=>unreachable!()};assert_eq!(value&(n.z|n.o),n.o);values.push(value);}values}
 fn value(&self,e:E,values:&[u64])->u64{if e.node==0{e.mask}else{values[e.node as usize-1]^e.mask}}
}
fn construct(p:&Program,initial_q:&[u64],initial_b:&[u64])->Result<(Aig,Vec<E>),usize>{let mut a=Aig::default();let mut q:Vec<_>=initial_q.iter().map(|&v|E::constant(v)).collect();let mut c=vec![E::constant(0);p.versions];for(i,&v)in initial_b.iter().enumerate(){c[i]=E::constant(v);}for(i,n)in p.nodes.iter().enumerate(){if a.nodes.len()>1000000{return Err(i);}let mut g=E::constant(u64::MAX);for &v in &p.guards[n.g as usize]{g=a.and(g,c[v as usize]);}let t=n.t as usize;match n.k{QX=>q[t]=a.xor(q[t],g),QCX=>{let v=a.and(g,q[n.a as usize]);q[t]=a.xor(q[t],v);},QCCX=>{let v=a.and(q[n.a as usize],q[n.b as usize]);let v=a.and(g,v);q[t]=a.xor(q[t],v);},QSWAP=>{let v=a.xor(q[t],q[n.a as usize]);let v=a.and(g,v);q[t]=a.xor(q[t],v);q[n.a as usize]=a.xor(q[n.a as usize],v);},QZERO=>q[t]=a.and(q[t],g.flip(u64::MAX)),CINV=>c[t]=a.xor(c[n.a as usize],g),CZERO=>c[t]=a.and(c[n.a as usize],g.flip(u64::MAX)),CONE=>c[t]=a.and(c[n.a as usize].flip(u64::MAX),g.flip(u64::MAX)).flip(u64::MAX),CRNG=>{let r=a.random(n.r);c[t]=a.ite(g,r,c[n.a as usize]);},_=>unreachable!()}}Ok((a,q))}
pub(super)fn audit(p:&Program,ops:&[quantum_ecc::circuit::Op],outputs:&[usize],fixtures:&[serde_json::Value])->serde_json::Value{
 use quantum_ecc::sim::Simulator;use quantum_ecc::circuit::{analyze_ops,QubitOrBit};let curve=super::audit_curve();let(_,_,_,regs)=analyze_ops(ops.iter());let mut rows=vec![];let mut noise=0xa8d7135f23649b01u64;
 for(batch,inputs)in fixtures.chunks(64).enumerate(){let valid=if inputs.len()==64{u64::MAX}else{(1u64<<inputs.len())-1};let mut empty=super::AuditWords{v:vec![],at:0};let mut init=Simulator::new(p.nq,p.nb,&mut empty);let mut expected=vec![0u64;p.nq];for(lane,f)in inputs.iter().enumerate(){let k1=f["k1"].as_str().unwrap().parse().unwrap();let k2=f["k2"].as_str().unwrap().parse().unwrap();let a=curve.mul(curve.gx,curve.gy,k1);let b=curve.mul(curve.gx,curve.gy,k2);let e=curve.add(a.0,a.1,b.0,b.1);for(i,v)in[a.0,a.1,b.0,b.1].into_iter().enumerate(){init.set_register(&regs[i],v,lane);}for(i,v)in[e.0,e.1].into_iter().enumerate(){for(bit,item)in regs[i].iter().enumerate(){match item{QubitOrBit::Qubit(q)=>expected[q.0 as usize]|=(v.bit(bit)as u64)<<lane,_=>panic!("quantum outputs")}}}}let q=init.qubits.clone();let bits=init.bits.clone();drop(init);let start=std::time::Instant::now();let(a,result)=match construct(p,&q,&bits){Ok(v)=>v,Err(at)=>{rows.push(serde_json::json!({"batch":batch,"status":"INCONCLUSIVE_NODE_BUDGET","at":at}));continue;}};let seconds=start.elapsed().as_secs_f64();let mut wrong=0;let mut known_bits=0u64;let mut fully_known=valid;for &q in outputs{let(z,o)=a.known(result[q]);known_bits+=((z|o)&valid).count_ones()as u64;fully_known&=z|o;wrong|=(o^expected[q])&(z|o)&valid;}let mut concrete=vec![];
  for pattern in 0..3{let words:Vec<u64>=(0..p.rng).map(|_|if pattern==0{0}else if pattern==1{u64::MAX}else{noise=noise.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);noise}).collect();let values=a.evaluate(&words);let mut rng=super::AuditWords{v:words.iter().flat_map(|v|v.to_le_bytes()).collect(),at:0};let mut sim=Simulator::new(p.nq,p.nb,&mut rng);sim.qubits.copy_from_slice(&q);sim.bits.copy_from_slice(&bits);sim.apply_iter(ops.iter());let mut actual_wrong=0;for &q in outputs{assert_eq!(a.value(result[q],&values)&valid,sim.qubits[q]&valid,"wordAIG/protected batch{batch} pattern{pattern} wire{q}");actual_wrong|=(sim.qubits[q]^expected[q])&valid;}assert_eq!(wrong&!actual_wrong,0,"false wrongpoint certificate");drop(sim);assert_eq!(rng.at,p.rng*8);concrete.push(serde_json::json!({"pattern":pattern,"wrong_mask":format!("{actual_wrong:016x}"),"wrong_shots":actual_wrong.count_ones()}));}
  rows.push(serde_json::json!({"batch":batch,"inputs":inputs.len(),"word_boolean_nodes":a.nodes.len(),"build_seconds":seconds,"known_output_bits":known_bits,"fully_known_shots":fully_known.count_ones(),"certified_wrong_shots":wrong.count_ones(),"certified_wrong_mask":format!("{wrong:016x}"),"protected_patterns":concrete,"protected_fullstream_comparisons":3}));eprintln!("WORD_PROOF_BATCH_COMPLETE batch={batch} known_bits={known_bits} certified_wrong={} nodes={} seconds={seconds}",wrong.count_ones(),a.nodes.len());
 }serde_json::json!({"status":"EXACT_SOURCE_WORD_BOOLEAN_VERIFIER_FIXTURE_AUDIT_NOT_A_NONCE_SCREEN","batches":rows,"fixtures":fixtures.len(),"nonce_screens":0,"nonce_rejections":0,"scope":"All original measurement words arbitrary64bit symbols. Constant masks, complete expression keys and exact Boolean identities only. Known output bits certify wrong values; unknown never rejects. Frozen oldsource/cache and fixed fixtures only, not a general currentparent filter or quantumrecord. Full originalFS qualification mandatory before any production rejection."})
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn exact_masked_word_identities_cover_all_four_lane_assignments(){let mut a=Aig::default();let x=a.random(0);let y=a.random(1);let z=a.random(2);let masked=a.and(x.flip(0b1010),y.flip(0b0110));let sum=a.xor(masked,z.flip(0b1100));let root=a.ite(x.flip(0b1001),sum,y);for bits in 0..4096{let words=[bits&15,(bits>>4)&15,(bits>>8)&15];let values=a.evaluate(&words);let want=((words[0]^0b1001)&(((words[0]^0b1010)&(words[1]^0b0110))^(words[2]^0b1100)))|(!(words[0]^0b1001)&words[1]);assert_eq!(a.value(root,&values),want);}}
 #[test]fn equal_random_words_with_different_masks_remain_exact_and_cancel(){let mut a=Aig::default();let x=a.random(0);let and=a.and(x.flip(0xa55a),x.flip(0x5aa5));let cancel=a.xor(x.flip(0x4444),x.flip(0x1111));assert_eq!(cancel,E::constant(0x5555));for word in[0,u64::MAX,0x123456789abcdef0,0x5aa5]{let values=a.evaluate(&[word]);assert_eq!(a.value(and,&values),(word^0xa55a)&(word^0x5aa5));}let zero=a.and(x,E::constant(0));let known=a.known(zero);assert_eq!(known,(u64::MAX,0));}
 #[test]fn unrelated_random_words_never_become_sampled_constants(){let mut a=Aig::default();let x=a.random(0);let y=a.random(1);let xy=a.xor(x,y);assert_ne!(xy.node,0);assert_eq!(a.known(xy),(0,0));let v=a.and(x,y);assert_eq!(a.known(v),(0,0));for words in[[0,0],[0,u64::MAX],[u64::MAX,0],[u64::MAX,u64::MAX]]{let values=a.evaluate(&words);assert_eq!(a.value(xy,&values),words[0]^words[1]);assert_eq!(a.value(v,&values),words[0]&words[1]);}}
}
